<?php
if(!defined('ABSPATH')){exit;}
final class NVConsult_Core_System_Status{
 public static function init():void{add_action('admin_menu',[self::class,'menu'],23);}
 public static function menu():void{if(current_user_can('manage_options'))add_submenu_page('edit.php?post_type=nv_application',__('Release Readiness','nvconsult-core'),__('Release Readiness','nvconsult-core'),'manage_options','nvconsult-release-readiness',[self::class,'render']);}
 public static function render():void{$checks=[];$checks[]=[__('HTTPS','nvconsult-core'),is_ssl(),__('Required before real applicant data.','nvconsult-core')];$checks[]=[__('Cron scheduled','nvconsult-core'),(bool)wp_next_scheduled('nvconsult_daily_followups'),__('Needed for reminders and automation.','nvconsult-core')];$checks[]=[__('Permalinks','nvconsult-core'),(bool)get_option('permalink_structure'),__('Required for reliable REST/front-end routing.','nvconsult-core')];$checks[]=[__('Upload storage writable','nvconsult-core'),wp_is_writable(wp_upload_dir()['basedir']),__('Required for applicant documents.','nvconsult-core')];$checks[]=[__('OpenAI configured','nvconsult-core'),(bool)getenv('OPENAI_API_KEY'),__('Optional; AI features remain disabled without it.','nvconsult-core')];$critical=array_filter($checks,static fn($c)=>!$c[1]&&$c[0]!==__('OpenAI configured','nvconsult-core'));echo'<div class="wrap"><h1>'.esc_html__('NVConsult Release Readiness','nvconsult-core').'</h1><p><strong>'.esc_html($critical?__('Not ready for production','nvconsult-core'):__('Environment checks passed','nvconsult-core')).'</strong></p><table class="widefat striped" style="max-width:900px"><thead><tr><th>'.esc_html__('Check','nvconsult-core').'</th><th>'.esc_html__('Status','nvconsult-core').'</th><th>'.esc_html__('Why it matters','nvconsult-core').'</th></tr></thead><tbody>';foreach($checks as$c)printf('<tr><td>%s</td><td><strong>%s</strong></td><td>%s</td></tr>',esc_html($c[0]),esc_html($c[1]?__('PASS','nvconsult-core'):__('ACTION','nvconsult-core')),esc_html($c[2]));echo'</tbody></table><p>'.esc_html__('Environment checks are necessary but do not replace staging regression, authorization and document-access tests.','nvconsult-core').'</p></div>';}
}
